// Image table generated by scripts/sync-images.mjs from live-images.json, the generated set and
// image-map.json (source URLs stay out of the bundle).
import images from "@/content/images.gen.json";

/** One image slot: a real photo of the client's work or a generated ambience image. */
export type AnyImage = {
  id: string;
  /** Fallback src (largest WebP). */
  file: string;
  /** Verbatim alt from the live site; "" for decorative generated images. */
  alt: string;
  /** The file exists in public/ (else the navy placeholder renders). */
  ok?: boolean | undefined;
  w?: number | undefined;
  h?: number | undefined;
  /** object-position focal point for art-directed crops. */
  pos?: string | undefined;
  /** File stem of the responsive variants, when it differs from `file` (generated set). */
  stem?: string | undefined;
  /** Widths of the <stem>-<w>.webp variants. */
  vw?: number[] | undefined;
  /** Width of the <stem>-<w>.avif variant. */
  aw?: number | undefined;
};

/** A real image of the client's work, extracted from ybcompany.ma (scripts/extract-live.mjs). */
export type LiveImage = AnyImage;

const live = images.live as Record<string, LiveImage[]>;
const slots = images.slots as Record<string, AnyImage>;
const heroes = images.heroes as Record<string, AnyImage>;

/** All live images of a page, in document order (banner first). */
export function pageImages(page: string): LiveImage[] {
  return live[page] ?? [];
}

/** Live images of a page excluding the banner, sliced by 1-based content index (inclusive). */
export function liveRange(page: string, from: number, to: number): LiveImage[] {
  return pageImages(page).filter((i) => {
    const m = /-(\d+)$/.exec(i.id);
    if (!m || i.id.includes("banner")) return false;
    const n = Number(m[1]);
    return n >= from && n <= to;
  });
}

export function liveImage(id: string): LiveImage {
  const page = id.replace(/-(banner(-\d+)?|\d+)$/, "");
  const found = pageImages(page).find((i) => i.id === id);
  if (!found) throw new Error(`Unknown live image ${id}`);
  return found;
}

export function banner(page: string): LiveImage | undefined {
  return pageImages(page).find((i) => i.id === `${page}-banner`);
}

/** A visual slot (step, card, panel, hover reveal…) as mapped in image-map.json. */
export function ambienceImage(id: string): AnyImage {
  const a = slots[id];
  if (!a) throw new Error(`Unknown image slot ${id}`);
  return a;
}

/** The page's hero image (image-map.json), also used for its mega-menu preview. */
export function heroImage(page: string): AnyImage | undefined {
  return heroes[page];
}

function stemOf(im: AnyImage): string {
  return im.stem ?? im.file.replace(/\.webp$/, "");
}

/** WebP srcset: the variants plus the original file. */
export function webpSrcSet(im: AnyImage): string | undefined {
  if (!im.vw?.length) return undefined;
  const stem = stemOf(im);
  const list = im.vw.map((w) => `${stem}-${w}.webp ${w}w`);
  if (!im.stem && im.w) list.push(`${im.file} ${im.w}w`);
  return list.join(", ");
}

export function avifSrcSet(im: AnyImage): string | undefined {
  return im.aw ? `${stemOf(im)}-${im.aw}.avif ${im.aw}w` : undefined;
}
